(function(){
  var KW='select from where group by order by having limit offset join left join right join inner join outer join on and or union union all insert into values update set delete from create table alter table drop table as distinct count sum avg min max case when then else end in not null is like between desc asc by intersect except';
  function fmt(sql){
    sql=String(sql==null?'':sql);
    var holes=[];
    sql=sql.replace(/'(?:[^']|'')*'|"(?:[^"]|"")*"|--[^\n]*|\/\*[\s\S]*?\*\//g,function(m){holes.push(m);return '\u0000'+(holes.length-1)+'\u0000';});
    sql=sql.replace(/\b(select|from|where|group by|order by|having|limit|offset|join|left join|right join|inner join|outer join|on|and|or|union|union all|insert into|values|update|set|delete from|create table|alter table|drop table|as|distinct|count|sum|avg|min|max|case|when|then|else|end|in|not|null|is|like|between|desc|asc|by)\b/gi,function(m){return m.toUpperCase();});
    sql=sql.replace(/\s*(SELECT|FROM|WHERE|GROUP BY|ORDER BY|HAVING|LIMIT|OFFSET|LEFT JOIN|RIGHT JOIN|INNER JOIN|OUTER JOIN|JOIN|UNION ALL|UNION|INSERT INTO|VALUES|UPDATE|SET|DELETE FROM|CREATE TABLE|ALTER TABLE|DROP TABLE)\b/g,function(m){return '\n'+m.trim();});
    sql=sql.replace(/\u0000(\d+)\u0000/g,function(m,i){return holes[+i];});
    return {value:sql.replace(/^\n+/,'').replace(/\n\s*\n/g,'\n').trim()};
  }
  var API={fmt:fmt};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__SqlFmtForge__=API;
})();
